import pyomo.environ as pyo

DATA = {
    "media": ["television", "radio", "newspaper"],
    "exposure": {
        "television": 20000,
        "radio": 2000,
        "newspaper": 9000,
    },
    "cost": {
        "television": 15000,
        "radio": 6000,
        "newspaper": 4000,
    },
    "budget": 100000,
    "max_ads": {
        "television": 4,
        "radio": 10,
        "newspaper": 7,
    },
    "max_total_ads": 15,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Set of advertising media
    model.MEDIA = pyo.Set(initialize=d["media"])

    # Decision variable: number of ads/commercials per medium
    def ads_bounds(m, medium):
        return (0, d["max_ads"][medium])

    model.ads = pyo.Var(
        model.MEDIA,
        domain=pyo.NonNegativeIntegers,
        bounds=ads_bounds,
    )

    # Objective: maximize total exposure
    def exposure_rule(m):
        return sum(d["exposure"][medium] * m.ads[medium] for medium in m.MEDIA)

    model.obj = pyo.Objective(expr=exposure_rule, sense=pyo.maximize)

    # Budget constraint
    def budget_rule(m):
        return sum(d["cost"][medium] * m.ads[medium] for medium in m.MEDIA) <= d["budget"]

    model.budget_constraint = pyo.Constraint(rule=budget_rule)

    # Per-medium maximum constraints
    def max_ads_rule(m, medium):
        return m.ads[medium] <= d["max_ads"][medium]

    model.max_ads_constraint = pyo.Constraint(model.MEDIA, rule=max_ads_rule)

    # Total number of ads/commercials constraint
    def total_ads_rule(m):
        return sum(m.ads[medium] for medium in m.MEDIA) <= d["max_total_ads"]

    model.total_ads_constraint = pyo.Constraint(rule=total_ads_rule)

    return model


